css:
.sd { --sd-gold: #B98A2E; display: flex; flex-direction: column; align-items: center; gap: var(--os-space-xs); text-align: center; }
.sd__emblem { width: min(520px, 100%); height: auto; fill: none; stroke: var(--sd-gold); stroke-width: 1; }
.sd__diamond { fill: var(--sd-gold); stroke: none; }
.sd__seed { stroke-width: .9; }
.sd__dots { stroke-dasharray: .8 3; }
.sd__line { margin: 0; font-family: var(--os-font-heading); font-style: italic; font-size: var(--os-type-h3-font-size); color: var(--os-color-heading); }
